/// NEV log — in-game narrative/event log, ported from gold_python/core/nev.py.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum EventKind {
    ActionApplied,
    StateTransition,
    RuleViolation,
    Achievement,
    ResourceDelta,
    EntitySpawn,
    EntityDespawn,
    Terminal,
    Debug,
}

impl EventKind {
    pub fn as_str(&self) -> &'static str {
        match self {
            EventKind::ActionApplied => "action_applied",
            EventKind::StateTransition => "state_transition",
            EventKind::RuleViolation => "rule_violation",
            EventKind::Achievement => "achievement",
            EventKind::ResourceDelta => "resource_delta",
            EventKind::EntitySpawn => "entity_spawn",
            EventKind::EntityDespawn => "entity_despawn",
            EventKind::Terminal => "terminal",
            EventKind::Debug => "debug",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum EventSeverity {
    Info,
    Warn,
    Error,
}

impl EventSeverity {
    pub fn as_str(&self) -> &'static str {
        match self {
            EventSeverity::Info => "info",
            EventSeverity::Warn => "warn",
            EventSeverity::Error => "error",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EventRecord {
    pub step_index: i64,
    pub sim_tick: i64,
    pub episode_id: String,
    pub kind: EventKind,
    pub severity: EventSeverity,
    pub message: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub action: Option<HashMap<String, serde_json::Value>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub transition: Option<HashMap<String, serde_json::Value>>,
    #[serde(default)]
    pub payload: HashMap<String, serde_json::Value>,
}

impl EventRecord {
    pub fn to_dict(&self) -> HashMap<String, serde_json::Value> {
        let mut m = HashMap::new();
        m.insert("step_index".into(), serde_json::Value::Number(self.step_index.into()));
        m.insert("sim_tick".into(), serde_json::Value::Number(self.sim_tick.into()));
        m.insert("episode_id".into(), serde_json::Value::String(self.episode_id.clone()));
        m.insert("kind".into(), serde_json::Value::String(self.kind.as_str().into()));
        m.insert("severity".into(), serde_json::Value::String(self.severity.as_str().into()));
        m.insert("message".into(), serde_json::Value::String(self.message.clone()));
        if let Some(ref a) = self.action {
            m.insert("action".into(), serde_json::to_value(a).unwrap_or_default());
        }
        if let Some(ref t) = self.transition {
            m.insert("transition".into(), serde_json::to_value(t).unwrap_or_default());
        }
        if !self.payload.is_empty() {
            m.insert("payload".into(), serde_json::to_value(&self.payload).unwrap_or_default());
        }
        m
    }
}

#[derive(Debug, Clone)]
pub struct NevLog {
    pub events: Vec<EventRecord>,
}

impl NevLog {
    pub fn new() -> Self {
        NevLog { events: Vec::new() }
    }

    pub fn cursor(&self) -> usize {
        self.events.len()
    }

    pub fn append(&mut self, record: EventRecord) {
        self.events.push(record);
    }

    pub fn legacy_strings(&self) -> Vec<String> {
        self.events.iter().map(|e| e.message.clone()).collect()
    }

    pub fn export(&self) -> Vec<HashMap<String, serde_json::Value>> {
        self.events.iter().map(|e| e.to_dict()).collect()
    }
}

/// Policy registry — ported from registry.py.
/// Each policy takes (board, turn, seed, ply) and returns a position.

use sha2::{Sha256, Digest};
use std::collections::HashMap;

use crate::board::{self, CORNERS, EDGES, CENTER, WIN_LINES};

pub type PolicyFn = fn(&[String; 9], &str, u64, u64) -> usize;

/// Build the full policy map keyed by policy_id.
pub fn policy_map() -> HashMap<&'static str, PolicyFn> {
    let mut m: HashMap<&'static str, PolicyFn> = HashMap::new();
    m.insert("first_legal_v1", first_legal);
    m.insert("last_legal_v1", last_legal);
    m.insert("center_first_v1", center_first);
    m.insert("corner_first_v1", corner_first);
    m.insert("edge_first_v1", edge_first);
    m.insert("win_block_center_v1", win_block_center);
    m.insert("block_win_center_v1", block_win_center);
    m.insert("mirror_preferred_v1", mirror_preferred);
    m.insert("seeded_legal_v1", seeded_legal);
    m.insert("seeded_win_block_v1", seeded_win_block);
    m
}

pub fn agent_mark(agent_id: &str) -> &str {
    match agent_id {
        "agent_0" => "X",
        "agent_1" => "O",
        _ => panic!("unknown agent: {agent_id}"),
    }
}

pub fn mark_to_agent(mark: &str) -> &str {
    match mark {
        "X" => "agent_0",
        "O" => "agent_1",
        _ => panic!("unknown mark: {mark}"),
    }
}

// --- helper: deterministic SHA-256 based choice ---

fn deterministic_choice(legal: &[usize], key: &str) -> usize {
    let mut hasher = Sha256::new();
    hasher.update(key.as_bytes());
    let digest = hasher.finalize();
    let r = u64::from_le_bytes(digest[..8].try_into().unwrap());
    legal[(r as usize) % legal.len()]
}

// --- helper: find a winning move for a given mark ---

fn find_win(board: &[String; 9], mark: &str) -> Option<usize> {
    for &(a, b, c) in WIN_LINES {
        let cells = [board[a].as_str(), board[b].as_str(), board[c].as_str()];
        let count_mark = cells.iter().filter(|&&c| c == mark).count();
        let count_empty = cells.iter().filter(|&&c| c.is_empty()).count();
        if count_mark == 2 && count_empty == 1 {
            if board[a].is_empty() { return Some(a); }
            if board[b].is_empty() { return Some(b); }
            if board[c].is_empty() { return Some(c); }
        }
    }
    None
}

fn find_block(board: &[String; 9], mark: &str) -> Option<usize> {
    let opponent = if mark == "X" { "O" } else { "X" };
    find_win(board, opponent)
}

// --- policy implementations ---

pub fn first_legal(board: &[String; 9], _turn: &str, _seed: u64, _ply: u64) -> usize {
    for i in 0..9 {
        if board[i].is_empty() {
            return i;
        }
    }
    panic!("no legal moves");
}

pub fn last_legal(board: &[String; 9], _turn: &str, _seed: u64, _ply: u64) -> usize {
    for i in (0..9).rev() {
        if board[i].is_empty() {
            return i;
        }
    }
    panic!("no legal moves");
}

pub fn center_first(board: &[String; 9], _turn: &str, _seed: u64, _ply: u64) -> usize {
    let legal: Vec<usize> = board::legal_positions(board);
    if legal.contains(&CENTER) {
        return CENTER;
    }
    for &e in EDGES {
        if legal.contains(&e) {
            return e;
        }
    }
    for &c in CORNERS {
        if legal.contains(&c) {
            return c;
        }
    }
    legal[0]
}

pub fn corner_first(board: &[String; 9], _turn: &str, _seed: u64, _ply: u64) -> usize {
    let legal: Vec<usize> = board::legal_positions(board);
    for &c in CORNERS {
        if legal.contains(&c) {
            return c;
        }
    }
    if legal.contains(&CENTER) {
        return CENTER;
    }
    for &e in EDGES {
        if legal.contains(&e) {
            return e;
        }
    }
    legal[0]
}

pub fn edge_first(board: &[String; 9], _turn: &str, _seed: u64, _ply: u64) -> usize {
    let legal: Vec<usize> = board::legal_positions(board);
    for &e in EDGES {
        if legal.contains(&e) {
            return e;
        }
    }
    for &c in CORNERS {
        if legal.contains(&c) {
            return c;
        }
    }
    if legal.contains(&CENTER) {
        return CENTER;
    }
    legal[0]
}

pub fn win_block_center(board: &[String; 9], turn: &str, _seed: u64, _ply: u64) -> usize {
    let legal: Vec<usize> = board::legal_positions(board);
    if let Some(pos) = find_win(board, turn) {
        return pos;
    }
    if let Some(pos) = find_block(board, turn) {
        return pos;
    }
    if legal.contains(&CENTER) {
        return CENTER;
    }
    for &c in CORNERS {
        if legal.contains(&c) {
            return c;
        }
    }
    legal[0]
}

pub fn block_win_center(board: &[String; 9], turn: &str, _seed: u64, _ply: u64) -> usize {
    let legal: Vec<usize> = board::legal_positions(board);
    if let Some(pos) = find_block(board, turn) {
        return pos;
    }
    if let Some(pos) = find_win(board, turn) {
        return pos;
    }
    if legal.contains(&CENTER) {
        return CENTER;
    }
    for &c in CORNERS {
        if legal.contains(&c) {
            return c;
        }
    }
    legal[0]
}

pub fn mirror_preferred(board: &[String; 9], turn: &str, _seed: u64, _ply: u64) -> usize {
    let opponent = if turn == "X" { "O" } else { "X" };
    let legal: Vec<usize> = board::legal_positions(board);
    for (i, cell) in board.iter().enumerate() {
        if cell == opponent {
            let mirror = 8 - i;
            if legal.contains(&mirror) {
                return mirror;
            }
        }
    }
    center_first(board, turn, _seed, _ply)
}

pub fn seeded_legal(board: &[String; 9], _turn: &str, seed: u64, ply: u64) -> usize {
    let legal = board::legal_positions(board);
    let key = format!("seeded_legal_v1:{seed}:{ply}");
    deterministic_choice(&legal, &key)
}

pub fn seeded_win_block(board: &[String; 9], turn: &str, seed: u64, ply: u64) -> usize {
    if let Some(pos) = find_win(board, turn) {
        return pos;
    }
    if let Some(pos) = find_block(board, turn) {
        return pos;
    }
    let legal = board::legal_positions(board);
    let key = format!("seeded_win_block_v1:{seed}:{ply}");
    deterministic_choice(&legal, &key)
}

/// Public/private state split for Tic-Tac-Toe, ported from gold_python/state.py.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PublicState {
    pub board: [String; 9],
    pub turn: String,
    pub winner: Option<String>,
}

impl PublicState {
    pub fn new() -> Self {
        PublicState {
            board: Default::default(),
            turn: "X".to_string(),
            winner: None,
        }
    }

    pub fn to_dict(&self) -> HashMap<String, serde_json::Value> {
        let mut m = HashMap::new();
        let board_val: Vec<serde_json::Value> = self.board.iter().map(|s| serde_json::Value::String(s.clone())).collect();
        m.insert("board".into(), serde_json::Value::Array(board_val));
        m.insert("turn".into(), serde_json::Value::String(self.turn.clone()));
        m.insert("winner".into(), match &self.winner {
            Some(w) => serde_json::Value::String(w.clone()),
            None => serde_json::Value::Null,
        });
        m
    }

    pub fn diff(&self, other: &PublicState) -> HashMap<String, serde_json::Value> {
        let mut changes = HashMap::new();
        if self.board != other.board {
            let mut d = HashMap::new();
            d.insert("from".into(), serde_json::to_value(&other.board).unwrap_or_default());
            d.insert("to".into(), serde_json::to_value(&self.board).unwrap_or_default());
            changes.insert("board".into(), serde_json::Value::Object(d.into_iter().collect()));
        }
        if self.turn != other.turn {
            let mut d = HashMap::new();
            d.insert("from".into(), serde_json::Value::String(other.turn.clone()));
            d.insert("to".into(), serde_json::Value::String(self.turn.clone()));
            changes.insert("turn".into(), serde_json::Value::Object(d.into_iter().collect()));
        }
        if self.winner != other.winner {
            let mut d = HashMap::new();
            d.insert("from".into(), serde_json::to_value(&other.winner).unwrap_or_default());
            d.insert("to".into(), serde_json::to_value(&self.winner).unwrap_or_default());
            changes.insert("winner".into(), serde_json::Value::Object(d.into_iter().collect()));
        }
        changes
    }
}

impl Default for PublicState {
    fn default() -> Self {
        Self::new()
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PrivateState {
    pub episode_id: String,
    pub scenario_id: String,
    pub seed: u64,
    pub step_index: i64,
    pub ply: i64,
    pub reward_last: f64,
    pub total_reward: f64,
    pub terminated: bool,
    pub truncated: bool,
}

impl PrivateState {
    pub fn new() -> Self {
        PrivateState {
            episode_id: String::new(),
            scenario_id: String::new(),
            seed: 0,
            step_index: 0,
            ply: 0,
            reward_last: 0.0,
            total_reward: 0.0,
            terminated: false,
            truncated: false,
        }
    }

    pub fn to_dict(&self) -> HashMap<String, serde_json::Value> {
        let mut m = HashMap::new();
        m.insert("episode_id".into(), serde_json::Value::String(self.episode_id.clone()));
        m.insert("scenario_id".into(), serde_json::Value::String(self.scenario_id.clone()));
        m.insert("seed".into(), serde_json::Value::Number((self.seed as i64).into()));
        m.insert("step_index".into(), serde_json::Value::Number(self.step_index.into()));
        m.insert("ply".into(), serde_json::Value::Number(self.ply.into()));
        m.insert("reward_last".into(), serde_json::Value::Number(serde_json::Number::from_f64(self.reward_last).unwrap_or(0.into())));
        m.insert("total_reward".into(), serde_json::Value::Number(serde_json::Number::from_f64(self.total_reward).unwrap_or(0.into())));
        m.insert("terminated".into(), serde_json::Value::Bool(self.terminated));
        m.insert("truncated".into(), serde_json::Value::Bool(self.truncated));
        m
    }
}

impl Default for PrivateState {
    fn default() -> Self {
        Self::new()
    }
}

