/// Read one scenario entry as JSON on stdin, run it, output {"events": [...]} on stdout.
/// Ported from gold_python/scenarios.py::run_scenario.

use std::collections::HashMap;
use std::io::{self, Read};

use scenario::engine::{episode_id_for_task, TicTacToeEngine};
use scenario::policies::{self, mark_to_agent, PolicyFn};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("stdin read");
    let task: HashMap<String, serde_json::Value> =
        serde_json::from_str(&input).expect("stdin JSON parse");

    let scenario_id = task.get("scenario_id")
        .and_then(|v| v.as_str())
        .expect("scenario_id")
        .to_string();
    let seed: u64 = task.get("seed")
        .and_then(|v| v.as_i64()).map(|x| x as u64)
        .or_else(|| task.get("seed").and_then(|v| v.as_str()).and_then(|s| s.parse().ok()))
        .unwrap_or(0);
    let max_plies: i64 = task.get("max_plies")
        .and_then(|v| v.as_i64())
        .unwrap_or(9);
    let opening_moves: Vec<HashMap<String, serde_json::Value>> = task.get("opening_moves")
        .and_then(|v| v.as_array())
        .map(|arr| arr.iter().map(|v| {
            v.as_object().expect("opening move object")
                .iter().map(|(k, vv)| (k.clone(), vv.clone())).collect()
        }).collect())
        .unwrap_or_default();

    // Resolve policy IDs from either legacy or new format
    let policy_map = policies::policy_map();
    let agent_0_policy_id: &str;
    let agent_1_policy_id: &str;

    if let Some(p_obj) = task.get("agent_0_policy").and_then(|v| v.as_object()) {
        agent_0_policy_id = p_obj.get("policy_id").and_then(|v| v.as_str()).expect("policy_id");
        agent_1_policy_id = task.get("agent_1_policy").and_then(|v| v.as_object())
            .and_then(|o| o.get("policy_id").and_then(|v| v.as_str())).expect("policy_id");
    } else {
        agent_0_policy_id = task.get("agent_0_policy_id")
            .or_else(|| task.get("x_policy_id"))
            .and_then(|v| v.as_str())
            .expect("agent_0_policy_id");
        agent_1_policy_id = task.get("agent_1_policy_id")
            .or_else(|| task.get("o_policy_id"))
            .and_then(|v| v.as_str())
            .expect("agent_1_policy_id");
    }

    let agents: [(&str, PolicyFn); 2] = [
        ("agent_0", *policy_map.get(agent_0_policy_id).unwrap_or_else(|| panic!("unknown policy: {agent_0_policy_id}"))),
        ("agent_1", *policy_map.get(agent_1_policy_id).unwrap_or_else(|| panic!("unknown policy: {agent_1_policy_id}"))),
    ];

    // Resolve episode_id
    let task_id = task.get("task_id")
        .and_then(|v| v.as_str())
        .unwrap_or(&scenario_id);
    let episode_id = task.get("episode_id")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
        .unwrap_or_else(|| episode_id_for_task(&scenario_id, seed, Some(task_id)));

    let mut engine = TicTacToeEngine::new();
    engine.reset(&scenario_id, seed, Some(&episode_id), Some(task_id));

    // Apply opening moves
    for action in &opening_moves {
        engine.step(action);
    }

    // Policy-driven rollout
    let mut plies: i64 = 0;
    while !engine.private.terminated && !engine.private.truncated && plies < max_plies {
        let agent_id = mark_to_agent(&engine.public.turn);
        let (_, policy_fn) = agents.iter().find(|(a, _)| *a == agent_id).expect("agent in agents");
        let board_ref = &engine.public.board;
        let pos = policy_fn(board_ref, &engine.public.turn, seed, plies as u64);
        let mut action = HashMap::new();
        action.insert("player".into(), serde_json::Value::String(engine.public.turn.clone()));
        action.insert("position".into(), serde_json::Value::Number((pos as i64).into()));
        engine.step(&action);
        plies += 1;
    }

    // If rollout stopped, append DEBUG event
    if !engine.private.terminated && !engine.private.truncated {
        let mut p = HashMap::new();
        p.insert("max_plies".into(), serde_json::Value::Number(max_plies.into()));
        let record = scenario::nev::EventRecord {
            step_index: engine.private.step_index,
            sim_tick: engine.private.step_index,
            episode_id: engine.private.episode_id.clone(),
            kind: scenario::nev::EventKind::Debug,
            severity: scenario::nev::EventSeverity::Info,
            message: format!("RolloutStopped(max_plies={max_plies})"),
            action: None,
            transition: None,
            payload: p,
        };
        engine.nev.append(record);
    }

    let events = engine.nev.legacy_strings();
    let output = serde_json::json!({"events": events});
    println!("{}", serde_json::to_string(&output).expect("JSON output"));
}

/// Tic-Tac-Toe board primitives — ported from Python gold.

pub const WIN_LINES: &[(usize, usize, usize)] = &[
    (0, 1, 2), (3, 4, 5), (6, 7, 8),  // rows
    (0, 3, 6), (1, 4, 7), (2, 5, 8),  // columns
    (0, 4, 8), (2, 4, 6),             // diagonals
];

pub const CORNERS: &[usize] = &[0, 2, 6, 8];
pub const EDGES: &[usize] = &[1, 3, 5, 7];
pub const CENTER: usize = 4;

pub const AGENT_IDS: &[&str] = &["agent_0", "agent_1"];

/// Returns "X" or "O" for a winner, or None.
pub fn winner_for(board: &[String; 9]) -> Option<String> {
    for &(a, b, c) in WIN_LINES {
        if !board[a].is_empty() && board[a] == board[b] && board[b] == board[c] {
            return Some(board[a].clone());
        }
    }
    None
}

/// Returns all legal (empty) positions in order.
pub fn legal_positions(board: &[String; 9]) -> Vec<usize> {
    (0..9).filter(|&i| board[i].is_empty()).collect()
}

/// Authoritative Tic-Tac-Toe simulation engine — ported from gold_python/engine.py.

use sha2::{Sha256, Digest};
use std::collections::HashMap;

use crate::board::winner_for;
use crate::nev::{EventKind, EventRecord, EventSeverity, NevLog};
use crate::state::PublicState;

pub fn config_hash(scenario_id: &str, seed: u64) -> String {
    let input = format!("tictactoe-singleplayer:{scenario_id}:{seed}");
    let mut hasher = Sha256::new();
    hasher.update(input.as_bytes());
    let digest = hasher.finalize();
    format!("sha256:{}", hex::encode(digest))
}

pub fn episode_id_for_task(scenario_id: &str, seed: u64, task_id: Option<&str>) -> String {
    let key = task_id.unwrap_or(scenario_id);
    let input = format!("gamebench.tictactoe-singleplayer.episode:{key}:{seed}");
    let mut hasher = Sha256::new();
    hasher.update(input.as_bytes());
    let digest = hasher.finalize();
    hex::encode(&digest[..16]) // first 32 hex chars = 16 bytes
}

pub struct TicTacToeEngine {
    pub public: PublicState,
    pub private: crate::state::PrivateState,
    pub nev: NevLog,
}

impl TicTacToeEngine {
    pub const ENV_FAMILY: &'static str = "tictactoe-singleplayer";

    pub fn new() -> Self {
        TicTacToeEngine {
            public: PublicState::new(),
            private: crate::state::PrivateState::new(),
            nev: NevLog::new(),
        }
    }

    pub fn reset(
        &mut self,
        scenario_id: &str,
        seed: u64,
        episode_id: Option<&str>,
        task_id: Option<&str>,
    ) {
        self.public = PublicState::new();
        let resolved = episode_id.map(|s| s.to_string())
            .unwrap_or_else(|| episode_id_for_task(scenario_id, seed, task_id));
        self.private = crate::state::PrivateState {
            episode_id: resolved,
            scenario_id: scenario_id.to_string(),
            seed,
            step_index: 0,
            ply: 0,
            reward_last: 0.0,
            total_reward: 0.0,
            terminated: false,
            truncated: false,
        };
        self.nev = NevLog::new();
        self._append_nev(
            EventKind::StateTransition,
            &format!("GameStarted({scenario_id})"),
            None,
            None,
            Some({
                let mut p = HashMap::new();
                p.insert("scenario_id".into(), serde_json::Value::String(scenario_id.to_string()));
                p.insert("seed".into(), serde_json::Value::Number((seed as i64).into()));
                p
            }),
            EventSeverity::Info,
        );
    }

    pub fn step(&mut self, action: &HashMap<String, serde_json::Value>) {
        if self.private.terminated || self.private.truncated {
            let mut p = HashMap::new();
            p.insert("reason".into(), serde_json::Value::String("terminal".into()));
            self._append_nev(
                EventKind::RuleViolation,
                "game is already over",
                Some(action.clone()),
                None,
                Some(p),
                EventSeverity::Error,
            );
            return;
        }

        let player = action.get("player")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let position = action.get("position")
            .and_then(|v| v.as_i64())
            .unwrap_or(-1) as usize;

        if player != self.public.turn {
            let mut p = HashMap::new();
            p.insert("expected_turn".into(), serde_json::Value::String(self.public.turn.clone()));
            p.insert("player".into(), serde_json::Value::String(player.clone()));
            self._append_nev(
                EventKind::RuleViolation,
                &format!("expected {} to move", self.public.turn),
                Some(action.clone()),
                None,
                Some(p),
                EventSeverity::Error,
            );
            return;
        }

        if position >= 9 {
            let mut p = HashMap::new();
            p.insert("position".into(), serde_json::Value::Number((position as i64).into()));
            self._append_nev(
                EventKind::RuleViolation,
                "position out of range",
                Some(action.clone()),
                None,
                Some(p),
                EventSeverity::Error,
            );
            return;
        }

        if !self.public.board[position].is_empty() {
            let mut p = HashMap::new();
            p.insert("position".into(), serde_json::Value::Number((position as i64).into()));
            p.insert("cell".into(), serde_json::Value::String(self.public.board[position].clone()));
            self._append_nev(
                EventKind::RuleViolation,
                "position already occupied",
                Some(action.clone()),
                None,
                Some(p),
                EventSeverity::Error,
            );
            return;
        }

        let prev_public = PublicState {
            board: self.public.board.clone(),
            turn: self.public.turn.clone(),
            winner: self.public.winner.clone(),
        };

        self.public.board[position] = player.clone();
        self.private.ply += 1;
        self.private.step_index += 1;

        let mut act_map = HashMap::new();
        act_map.insert("player".into(), serde_json::Value::String(player.clone()));
        act_map.insert("position".into(), serde_json::Value::Number((position as i64).into()));

        let mut pay = HashMap::new();
        pay.insert("player".into(), serde_json::Value::String(player.clone()));
        pay.insert("position".into(), serde_json::Value::Number((position as i64).into()));

        let trans = self.public.diff(&prev_public);

        self._append_nev(
            EventKind::ActionApplied,
            &format!("MoveApplied({player},{position})"),
            Some(act_map),
            Some(trans),
            Some(pay),
            EventSeverity::Info,
        );

        let winner = winner_for(&self.public.board);
        if let Some(w) = winner {
            self.public.winner = Some(w.clone());
            self.private.terminated = true;
            self.private.reward_last = 1.0;
            self.private.total_reward += 1.0;
            let mut p = HashMap::new();
            p.insert("winner".into(), serde_json::Value::String(w.clone()));
            p.insert("reason".into(), serde_json::Value::String("win".into()));
            self._append_nev(
                EventKind::Terminal,
                &format!("GameEnded({w},win)"),
                None,
                None,
                Some(p),
                EventSeverity::Info,
            );
        } else if self.public.board.iter().all(|c| !c.is_empty()) {
            self.public.winner = Some("draw".to_string());
            self.private.terminated = true;
            self.private.reward_last = 0.0;
            let mut p = HashMap::new();
            p.insert("winner".into(), serde_json::Value::String("draw".into()));
            p.insert("reason".into(), serde_json::Value::String("draw".into()));
            self._append_nev(
                EventKind::Terminal,
                "GameEnded(draw,draw)",
                None,
                None,
                Some(p),
                EventSeverity::Info,
            );
        } else {
            let next_turn = if player == "X" { "O" } else { "X" };
            self.public.turn = next_turn.to_string();
            self.private.reward_last = 0.0;
            let mut p = HashMap::new();
            p.insert("turn".into(), serde_json::Value::String(next_turn.to_string()));
            self._append_nev(
                EventKind::StateTransition,
                &format!("TurnStarted({next_turn})"),
                None,
                None,
                Some(p),
                EventSeverity::Info,
            );
        }
    }

    fn _append_nev(
        &mut self,
        kind: EventKind,
        message: &str,
        action: Option<HashMap<String, serde_json::Value>>,
        transition: Option<HashMap<String, serde_json::Value>>,
        payload: Option<HashMap<String, serde_json::Value>>,
        severity: EventSeverity,
    ) {
        let record = EventRecord {
            step_index: self.private.step_index,
            sim_tick: self.private.step_index,
            episode_id: self.private.episode_id.clone(),
            kind,
            severity,
            message: message.to_string(),
            action,
            transition,
            payload: payload.unwrap_or_default(),
        };
        self.nev.append(record);
    }
}

pub mod board;
pub mod engine;
pub mod nev;
pub mod policies;
pub mod state;

/// NEV log — in-game narrative/event log, ported from gold_python/core/nev.py.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum EventKind {
    ActionApplied,
    StateTransition,
    RuleViolation,
    Achievement,
    ResourceDelta,
    EntitySpawn,
    EntityDespawn,
    Terminal,
    Debug,
}

impl EventKind {
    pub fn as_str(&self) -> &'static str {
        match self {
            EventKind::ActionApplied => "action_applied",
            EventKind::StateTransition => "state_transition",
            EventKind::RuleViolation => "rule_violation",
            EventKind::Achievement => "achievement",
            EventKind::ResourceDelta => "resource_delta",
            EventKind::EntitySpawn => "entity_spawn",
            EventKind::EntityDespawn => "entity_despawn",
            EventKind::Terminal => "terminal",
            EventKind::Debug => "debug",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum EventSeverity {
    Info,
    Warn,
    Error,
}

impl EventSeverity {
    pub fn as_str(&self) -> &'static str {
        match self {
            EventSeverity::Info => "info",
            EventSeverity::Warn => "warn",
            EventSeverity::Error => "error",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EventRecord {
    pub step_index: i64,
    pub sim_tick: i64,
    pub episode_id: String,
    pub kind: EventKind,
    pub severity: EventSeverity,
    pub message: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub action: Option<HashMap<String, serde_json::Value>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub transition: Option<HashMap<String, serde_json::Value>>,
    #[serde(default)]
    pub payload: HashMap<String, serde_json::Value>,
}

impl EventRecord {
    pub fn to_dict(&self) -> HashMap<String, serde_json::Value> {
        let mut m = HashMap::new();
        m.insert("step_index".into(), serde_json::Value::Number(self.step_index.into()));
        m.insert("sim_tick".into(), serde_json::Value::Number(self.sim_tick.into()));
        m.insert("episode_id".into(), serde_json::Value::String(self.episode_id.clone()));
        m.insert("kind".into(), serde_json::Value::String(self.kind.as_str().into()));
        m.insert("severity".into(), serde_json::Value::String(self.severity.as_str().into()));
        m.insert("message".into(), serde_json::Value::String(self.message.clone()));
        if let Some(ref a) = self.action {
            m.insert("action".into(), serde_json::to_value(a).unwrap_or_default());
        }
        if let Some(ref t) = self.transition {
            m.insert("transition".into(), serde_json::to_value(t).unwrap_or_default());
        }
        if !self.payload.is_empty() {
            m.insert("payload".into(), serde_json::to_value(&self.payload).unwrap_or_default());
        }
        m
    }
}

#[derive(Debug, Clone)]
pub struct NevLog {
    pub events: Vec<EventRecord>,
}

impl NevLog {
    pub fn new() -> Self {
        NevLog { events: Vec::new() }
    }

    pub fn cursor(&self) -> usize {
        self.events.len()
    }

    pub fn append(&mut self, record: EventRecord) {
        self.events.push(record);
    }

    pub fn legacy_strings(&self) -> Vec<String> {
        self.events.iter().map(|e| e.message.clone()).collect()
    }

    pub fn export(&self) -> Vec<HashMap<String, serde_json::Value>> {
        self.events.iter().map(|e| e.to_dict()).collect()
    }
}

/// Policy registry — ported from registry.py.
/// Each policy takes (board, turn, seed, ply) and returns a position.

use sha2::{Sha256, Digest};
use std::collections::HashMap;

use crate::board::{self, CORNERS, EDGES, CENTER, WIN_LINES};

pub type PolicyFn = fn(&[String; 9], &str, u64, u64) -> usize;

/// Build the full policy map keyed by policy_id.
pub fn policy_map() -> HashMap<&'static str, PolicyFn> {
    let mut m: HashMap<&'static str, PolicyFn> = HashMap::new();
    m.insert("first_legal_v1", first_legal);
    m.insert("last_legal_v1", last_legal);
    m.insert("center_first_v1", center_first);
    m.insert("corner_first_v1", corner_first);
    m.insert("edge_first_v1", edge_first);
    m.insert("win_block_center_v1", win_block_center);
    m.insert("block_win_center_v1", block_win_center);
    m.insert("mirror_preferred_v1", mirror_preferred);
    m.insert("seeded_legal_v1", seeded_legal);
    m.insert("seeded_win_block_v1", seeded_win_block);
    m
}

pub fn agent_mark(agent_id: &str) -> &str {
    match agent_id {
        "agent_0" => "X",
        "agent_1" => "O",
        _ => panic!("unknown agent: {agent_id}"),
    }
}

pub fn mark_to_agent(mark: &str) -> &str {
    match mark {
        "X" => "agent_0",
        "O" => "agent_1",
        _ => panic!("unknown mark: {mark}"),
    }
}

// --- helper: deterministic SHA-256 based choice ---

fn deterministic_choice(legal: &[usize], key: &str) -> usize {
    let mut hasher = Sha256::new();
    hasher.update(key.as_bytes());
    let digest = hasher.finalize();
    let r = u64::from_le_bytes(digest[..8].try_into().unwrap());
    legal[(r as usize) % legal.len()]
}

// --- helper: find a winning move for a given mark ---

fn find_win(board: &[String; 9], mark: &str) -> Option<usize> {
    for &(a, b, c) in WIN_LINES {
        let cells = [board[a].as_str(), board[b].as_str(), board[c].as_str()];
        let count_mark = cells.iter().filter(|&&c| c == mark).count();
        let count_empty = cells.iter().filter(|&&c| c.is_empty()).count();
        if count_mark == 2 && count_empty == 1 {
            if board[a].is_empty() { return Some(a); }
            if board[b].is_empty() { return Some(b); }
            if board[c].is_empty() { return Some(c); }
        }
    }
    None
}

fn find_block(board: &[String; 9], mark: &str) -> Option<usize> {
    let opponent = if mark == "X" { "O" } else { "X" };
    find_win(board, opponent)
}

// --- policy implementations ---

pub fn first_legal(board: &[String; 9], _turn: &str, _seed: u64, _ply: u64) -> usize {
    for i in 0..9 {
        if board[i].is_empty() {
            return i;
        }
    }
    panic!("no legal moves");
}

pub fn last_legal(board: &[String; 9], _turn: &str, _seed: u64, _ply: u64) -> usize {
    for i in (0..9).rev() {
        if board[i].is_empty() {
            return i;
        }
    }
    panic!("no legal moves");
}

pub fn center_first(board: &[String; 9], _turn: &str, _seed: u64, _ply: u64) -> usize {
    let legal: Vec<usize> = board::legal_positions(board);
    if legal.contains(&CENTER) {
        return CENTER;
    }
    for &e in EDGES {
        if legal.contains(&e) {
            return e;
        }
    }
    for &c in CORNERS {
        if legal.contains(&c) {
            return c;
        }
    }
    legal[0]
}

pub fn corner_first(board: &[String; 9], _turn: &str, _seed: u64, _ply: u64) -> usize {
    let legal: Vec<usize> = board::legal_positions(board);
    for &c in CORNERS {
        if legal.contains(&c) {
            return c;
        }
    }
    if legal.contains(&CENTER) {
        return CENTER;
    }
    for &e in EDGES {
        if legal.contains(&e) {
            return e;
        }
    }
    legal[0]
}

pub fn edge_first(board: &[String; 9], _turn: &str, _seed: u64, _ply: u64) -> usize {
    let legal: Vec<usize> = board::legal_positions(board);
    for &e in EDGES {
        if legal.contains(&e) {
            return e;
        }
    }
    for &c in CORNERS {
        if legal.contains(&c) {
            return c;
        }
    }
    if legal.contains(&CENTER) {
        return CENTER;
    }
    legal[0]
}

pub fn win_block_center(board: &[String; 9], turn: &str, _seed: u64, _ply: u64) -> usize {
    let legal: Vec<usize> = board::legal_positions(board);
    if let Some(pos) = find_win(board, turn) {
        return pos;
    }
    if let Some(pos) = find_block(board, turn) {
        return pos;
    }
    if legal.contains(&CENTER) {
        return CENTER;
    }
    for &c in CORNERS {
        if legal.contains(&c) {
            return c;
        }
    }
    legal[0]
}

pub fn block_win_center(board: &[String; 9], turn: &str, _seed: u64, _ply: u64) -> usize {
    let legal: Vec<usize> = board::legal_positions(board);
    if let Some(pos) = find_block(board, turn) {
        return pos;
    }
    if let Some(pos) = find_win(board, turn) {
        return pos;
    }
    if legal.contains(&CENTER) {
        return CENTER;
    }
    for &c in CORNERS {
        if legal.contains(&c) {
            return c;
        }
    }
    legal[0]
}

pub fn mirror_preferred(board: &[String; 9], turn: &str, _seed: u64, _ply: u64) -> usize {
    let opponent = if turn == "X" { "O" } else { "X" };
    let legal: Vec<usize> = board::legal_positions(board);
    for (i, cell) in board.iter().enumerate() {
        if cell == opponent {
            let mirror = 8 - i;
            if legal.contains(&mirror) {
                return mirror;
            }
        }
    }
    center_first(board, turn, _seed, _ply)
}

pub fn seeded_legal(board: &[String; 9], _turn: &str, seed: u64, ply: u64) -> usize {
    let legal = board::legal_positions(board);
    let key = format!("seeded_legal_v1:{seed}:{ply}");
    deterministic_choice(&legal, &key)
}

pub fn seeded_win_block(board: &[String; 9], turn: &str, seed: u64, ply: u64) -> usize {
    if let Some(pos) = find_win(board, turn) {
        return pos;
    }
    if let Some(pos) = find_block(board, turn) {
        return pos;
    }
    let legal = board::legal_positions(board);
    let key = format!("seeded_win_block_v1:{seed}:{ply}");
    deterministic_choice(&legal, &key)
}

/// Public/private state split for Tic-Tac-Toe, ported from gold_python/state.py.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PublicState {
    pub board: [String; 9],
    pub turn: String,
    pub winner: Option<String>,
}

impl PublicState {
    pub fn new() -> Self {
        PublicState {
            board: Default::default(),
            turn: "X".to_string(),
            winner: None,
        }
    }

    pub fn to_dict(&self) -> HashMap<String, serde_json::Value> {
        let mut m = HashMap::new();
        let board_val: Vec<serde_json::Value> = self.board.iter().map(|s| serde_json::Value::String(s.clone())).collect();
        m.insert("board".into(), serde_json::Value::Array(board_val));
        m.insert("turn".into(), serde_json::Value::String(self.turn.clone()));
        m.insert("winner".into(), match &self.winner {
            Some(w) => serde_json::Value::String(w.clone()),
            None => serde_json::Value::Null,
        });
        m
    }

    pub fn diff(&self, other: &PublicState) -> HashMap<String, serde_json::Value> {
        let mut changes = HashMap::new();
        if self.board != other.board {
            let mut d = HashMap::new();
            d.insert("from".into(), serde_json::to_value(&other.board).unwrap_or_default());
            d.insert("to".into(), serde_json::to_value(&self.board).unwrap_or_default());
            changes.insert("board".into(), serde_json::Value::Object(d.into_iter().collect()));
        }
        if self.turn != other.turn {
            let mut d = HashMap::new();
            d.insert("from".into(), serde_json::Value::String(other.turn.clone()));
            d.insert("to".into(), serde_json::Value::String(self.turn.clone()));
            changes.insert("turn".into(), serde_json::Value::Object(d.into_iter().collect()));
        }
        if self.winner != other.winner {
            let mut d = HashMap::new();
            d.insert("from".into(), serde_json::to_value(&other.winner).unwrap_or_default());
            d.insert("to".into(), serde_json::to_value(&self.winner).unwrap_or_default());
            changes.insert("winner".into(), serde_json::Value::Object(d.into_iter().collect()));
        }
        changes
    }
}

impl Default for PublicState {
    fn default() -> Self {
        Self::new()
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PrivateState {
    pub episode_id: String,
    pub scenario_id: String,
    pub seed: u64,
    pub step_index: i64,
    pub ply: i64,
    pub reward_last: f64,
    pub total_reward: f64,
    pub terminated: bool,
    pub truncated: bool,
}

impl PrivateState {
    pub fn new() -> Self {
        PrivateState {
            episode_id: String::new(),
            scenario_id: String::new(),
            seed: 0,
            step_index: 0,
            ply: 0,
            reward_last: 0.0,
            total_reward: 0.0,
            terminated: false,
            truncated: false,
        }
    }

    pub fn to_dict(&self) -> HashMap<String, serde_json::Value> {
        let mut m = HashMap::new();
        m.insert("episode_id".into(), serde_json::Value::String(self.episode_id.clone()));
        m.insert("scenario_id".into(), serde_json::Value::String(self.scenario_id.clone()));
        m.insert("seed".into(), serde_json::Value::Number((self.seed as i64).into()));
        m.insert("step_index".into(), serde_json::Value::Number(self.step_index.into()));
        m.insert("ply".into(), serde_json::Value::Number(self.ply.into()));
        m.insert("reward_last".into(), serde_json::Value::Number(serde_json::Number::from_f64(self.reward_last).unwrap_or(0.into())));
        m.insert("total_reward".into(), serde_json::Value::Number(serde_json::Number::from_f64(self.total_reward).unwrap_or(0.into())));
        m.insert("terminated".into(), serde_json::Value::Bool(self.terminated));
        m.insert("truncated".into(), serde_json::Value::Bool(self.truncated));
